/// `auto_stop_idle_minutes` on disk: a number of minutes, or `"off"`.
mod auto_stop_serde {
    use serde::{Deserialize, Deserializer, Serialize, Serializer, de::Error as _};

    #[derive(Serialize, Deserialize)]
    #[serde(untagged)]
    enum OnDisk {
        Minutes(u32),
        Word(String),
    }

    pub fn serialize<S: Serializer>(v: &Option<u32>, s: S) -> Result<S::Ok, S::Error> {
        match v {
            Some(m) => OnDisk::Minutes(*m).serialize(s),
            None => OnDisk::Word("off".into()).serialize(s),
        }
    }

    pub fn deserialize<'de, D: Deserializer<'de>>(d: D) -> Result<Option<u32>, D::Error> {
        match OnDisk::deserialize(d)? {
            OnDisk::Minutes(m) => Ok(Some(m)),
            OnDisk::Word(w) if w.eq_ignore_ascii_case("off") => Ok(None),
            OnDisk::Word(w) => Err(D::Error::custom(format!(
                "auto_stop_idle_minutes must be a number of minutes or \"off\", not {w:?}"
            ))),
        }
    }
}

export function juryCheck(critics, items, { seed = DEFAULT_SEED, B = DEFAULT_BOOTSTRAP } = {}) {
  const reports = criticReports(critics, items, seed, B);
  const pairs = diversityMatrix(critics, items);
  const inverted = [];
  for (let i = 0; i < reports.length; i++) {
    const row = reports[i];
    if (row.ci && row.ci.high < 0.5) inverted.push(row.id);
  }
  const duplicates = [];
  for (let i = 0; i < pairs.length; i++) {
    const pair = pairs[i];
    if (pair.errorConsistency !== null && pair.errorConsistency >= DUPLICATE_KAPPA) {
      duplicates.push({ a: pair.a, b: pair.b, errorConsistency: pair.errorConsistency });
    }
  }
  return {
    items: items.length,
    groups: sortedGroups(items).length,
    seed,
    bootstrap: B,
    critics: reports,
    pairs,
    inverted,
    duplicates,
  };
}

export function juryCheck(critics, items, {
  seed = DEFAULT_SEED,
  B = DEFAULT_BOOTSTRAP,
  recipes,
  allowUnproven = false,
  requireRecipe = false,
} = {}) {
  const reports = criticReports(critics, items, seed, B);
  const pairs = diversityMatrix(critics, items);
  const inverted = [];
  for (let i = 0; i < reports.length; i++) {
    const row = reports[i];
    if (row.ci && row.ci.high < 0.5) inverted.push(row.id);
  }
  const duplicates = [];
  for (let i = 0; i < pairs.length; i++) {
    const pair = pairs[i];
    if (pair.errorConsistency !== null && pair.errorConsistency >= DUPLICATE_KAPPA) {
      duplicates.push({ a: pair.a, b: pair.b, errorConsistency: pair.errorConsistency });
    }
  }
  const gate = recipeAssessments(critics, recipes, { allowUnproven, requireRecipe });
  for (let i = 0; i < reports.length; i++) {
    reports[i].recipe = gate.applied ? (gate.byId.get(reports[i].id) || null) : null;
  }
  return {
    items: items.length,
    groups: sortedGroups(items).length,
    seed,
    bootstrap: B,
    critics: reports,
    pairs,
    inverted,
    duplicates,
    excluded: gate.excluded,
    allowUnproven: gate.applied ? allowUnproven === true : false,
    requireRecipe: gate.applied ? requireRecipe === true : false,
  };
}

